using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed "Discriminator" to "$type". Keep the old name
            // so existing 500K documents remain readable without migration.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed id format from "Product|123" to "Product-123".
            // Use IdProperty with value generation to preserve the pipe-separated
            // format already stored in the container.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<PipeIdValueGenerator>();

            entity.HasIndex(p => p.Sku);
        });
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

